import { lazy } from 'react'

import { Image, List } from '@chakra-ui/react'

import { ImageWithComment, VideoWithComment, Period, PreiodCollapsible, Remarks, stackSheetsStyle } from '~/ui/layout/item/explanation'
import { HowToCraft } from '~/ui/items/common/mindOfInstructions'

import backsideVideo from './explanation/00-00.backside.mp4'
import backsidePicture from './explanation/00-00.backside.jpg'
import usageMethod01 from './explanation/01-01.method.jpg'
import usageMethod02 from './explanation/01-02.method.jpg'
import usageMethod03 from './explanation/01-03.method.jpg'
import point01 from './explanation/02-01.point.jpg'

const AutoDoorSingleLeafLink = lazy(() => import('~/ui/items/block/lego/autoDoorSingleLeaf/Link'));
const OpenSesameLink = lazy(() => import('~/ui/items/block/lego/openSesame/Link'));

const GearSlideLink = lazy(() => import('~/ui/items/block/lego/method/gearSlide/Link'));
const ConnectPattern01Link = lazy(() => import('~/ui/items/block/lego/method/connectPattern01/Link'));
const GearTransmissionLink = lazy(() => import('~/ui/items/block/lego/method/gearTransmission/Link'));
const BeltTransmissionLink = lazy(() => import('~/ui/items/block/lego/method/beltTransmission/Link'));


type ExplanationProp = {
  openDrawer: (kind: string, name: string) => () => void
}
export default function Explanation(prop: ExplanationProp) {
  const { openDrawer } = prop;
  
  return (
    <>
      <Period lemma='裏側：'>
        <VideoWithComment 
          videoNormal={backsideVideo} videoSmall={backsideVideo} thumbnailP={backsidePicture} commentMinWidth='15em'
          css={stackSheetsStyle}>
          裏から見ると、ハンドルを回すことで歯車が回転し、その回転でドアが開閉しているのが分かります。<br/>
          また、もう片側のドアを開閉する歯車へと回転を伝えるため、４つの歯車が設置されています。<br/>
          <Remarks mark='※'>
            "自動ドア"と言いつつ手で回していることには目を瞑ってください。<br/>
            "ドアの部分に手を触れずに開け閉めできる"の意味で自動ドアと表現しています。
          </Remarks>
        </VideoWithComment>
      </Period>
      <Period lemma='作り方 ＆ 思い付いたキッカケ：'>
        <HowToCraft />
        <ImageWithComment image={usageMethod01} contentAspectRatio='211 / 214' commentMinWidth='20em' css={stackSheetsStyle}>
          まずメインの歯車で片側のドアを開閉する部分。<br/>
          ここは<GearSlideLink openDrawer={openDrawer} />を使ってます。<br/>
        </ImageWithComment>
        <br/>
        <ImageWithComment image={usageMethod02} contentAspectRatio='211 / 214' commentMinWidth='20em' css={stackSheetsStyle}>
          次に "歯車を回すための軸" を下から受け止めて支えている部分。<br/>
          ここは<ConnectPattern01Link openDrawer={openDrawer} />で紹介しているブロックの組み方で作ってます。<br/>
        </ImageWithComment>
        <br/>
        <ImageWithComment image={usageMethod03} contentAspectRatio='211 / 214' commentMinWidth='20em' css={stackSheetsStyle}>
          最後は "もう片側のドアを動かす歯車" へ回転の力を伝えている部分。<br/>
          ここは<GearTransmissionLink openDrawer={openDrawer} />で、もう片側のドアを動かす歯車へ回転の力を伝えています。<br/>
          <Remarks mark='※'>
            "<AutoDoorSingleLeafLink />" を作った後、「やっぱり自動ドアと言えば両開きだよね〜」となり、もう一個のドアを動かす歯車を複数の歯車を連結させて回せれば〜と考えたのがキッカケだったりします
          </Remarks>
        </ImageWithComment>
        <br/>
        この３つを組み合わせて、ドアっぽく周囲をデコレーションしたら完成です。<br/>
        <br/>
        ドアは滑らかに開閉したいので、↓図のように "デコボコしていない平らなブロック" を敷き、その上にドアを置くと良い感じです。
        <Image src={point01} w='min(max(15em, 35%), 25em)' aspectRatio='105 / 47' loading='lazy' />
      </Period>
      <PreiodCollapsible lemma='補足：'>
        "片開き自動ドア" から "両開き" にする際に、もう片方へどうやって動きを伝えるかで次の２つがありました。<br/>
        <List.Root>
          <List.Item><BeltTransmissionLink openDrawer={openDrawer} /></List.Item>
          <List.Item><GearTransmissionLink openDrawer={openDrawer} /></List.Item>
        </List.Root>
        <br/>
        ここでは<GearTransmissionLink openDrawer={openDrawer} />を使っていますが、<BeltTransmissionLink openDrawer={openDrawer} />を使った例も別の作品(メニュー)で紹介しています。<br/>
        <br/>
        良かったら覗いてみてください。( "<OpenSesameLink />" と名前を付けています)<br/>
        <br/>
        人それぞれですが、娘はそれまであまり歯車に馴染みがなく、ちょっと難しそうと敬遠してたところがあったので、レベルを結構高めに設定しました。<br/>
        ただその後、「つなげて取り敢えず動かしてみて、その様子から改善していけば良いや〜」と考えられるようになったらしく、色々いじくってくれてます。
      </PreiodCollapsible>
    </>
  )
}

